mapper.select:
select ga.* from gl_account ga
join gl_account_organization gao on gao.gl_account_id = ga.gl_account_id

    join gl_account_type gat on gat.gl_account_type_id = ga.gl_account_type_id


    join work_effort_purpose_account wepa on wepa.gl_account_id = ga.gl_account_id
    join work_effort_purpose_type wept on wept.work_effort_purpose_type_id = wepa.work_effort_purpose_type_id

where
ga.account_type_enum_id = #{accountTypeEnumId,jdbcType=VARCHAR}
AND gao.organization_party_id = #{organizationId,jdbcType=VARCHAR}

    AND gat.is_reserved_account = #{isReservedAccount,jdbcType=VARCHAR}


    AND ga.RESP_CENTER_ID IS NOT NULL


    AND ga.resp_center_id = #{respCenterId}



    AND






    AND ga.gl_account_type_id = #{glAccountTypeId}


    AND ga.input_enum_id = #{inputEnumId}


    AND ga.detect_org_unit_id_flag = #{detectOrgUnitIdFlag}


    AND ga.debit_credit_default = #{debitCreditDefault}


    AND ga.period_type_id = #{periodTypeId}


    AND ga.current_status_id = #{currentStatusId}





order by
${orderBy} ${orderType},

ga.gl_account_id
